page.goto("https://insideairbnb.com/get-the-data/");
return page.evaluate(() => {
  const t = document.body.innerText;
  return ["Barcelona","Lisbon","Madrid","Athens"].map(c => {
    const out=[]; let i=-1;
    while((i=t.indexOf(c,i+1))>=0) out.push(t.slice(Math.max(0,i-60),i+80).replace(/\s+/g," "));
    return out;
  });
});
